import torch, time
import triton
import triton.language as tl

@triton.jit
def _copy(X, Y, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    tl.store(Y + offs, tl.load(X + offs))

@triton.jit
def _spin(Y, iters, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    a = tl.zeros([BLOCK], tl.float32) + pid
    for i in range(iters):
        a = a * 1.0001 + 0.5
    tl.store(Y + offs, a)

x = torch.rand(16, 64, 256, 256, device='cuda')
y = torch.empty_like(x)
numel = x.numel()
BLOCK = 8192
thrash = torch.empty((64, 1024, 1024), dtype=torch.int64, device='cuda')  # 512MB

def evt_time(n=10):
    def deco(fn):
        ts = []
        for _ in range(n):
            s = torch.cuda.Event(True); e = torch.cuda.Event(True)
            s.record(); fn(); e.record()
            torch.cuda.synchronize()
            ts.append(s.elapsed_time(e))
        return sum(ts)/len(ts), min(ts)
    return deco

copyfn = lambda: _copy[(numel//BLOCK,)](x, y, BLOCK=BLOCK, num_warps=8)

# 1. sustained: 100 copies between events
for _ in range(3): copyfn()
torch.cuda.synchronize()
s = torch.cuda.Event(True); e = torch.cuda.Event(True)
s.record()
for _ in range(100): copyfn()
e.record(); torch.cuda.synchronize()
print(f'sustained copy: {s.elapsed_time(e)/100:.4f} ms')

# 2. after read-only thrash (clean L2)
def t2():
    _ = thrash.float().sum()
    torch.cuda.synchronize()
    return evt_time()(copyfn)
print('copy after read thrash:', t2())

# 3. after dirty fill thrash (evaluator pattern)
def t3():
    thrash[:32].fill_(42)
    torch.cuda.synchronize()
    return evt_time()(copyfn)
print('copy after fill thrash:', t3())

# 4. clocks hot from spin kernel (no thrash), then copy
def t4():
    _spin[(132,)](y, 200000, BLOCK=1024, num_warps=8)  # ~ms busy
    torch.cuda.synchronize()
    return evt_time()(copyfn)
print('copy after spin (hot clocks):', t4())

# 5. hot clocks + sleep 5ms before timing
def t5():
    _spin[(132,)](y, 200000, BLOCK=1024, num_warps=8)
    torch.cuda.synchronize()
    time.sleep(0.005)
    return evt_time()(copyfn)
print('copy after spin + 5ms sleep:', t5())
EOF
