import torch
import triton
import triton.language as tl

@triton.jit
def _copy(X, Y, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    tl.store(Y + offs, tl.load(X + offs))

@triton.jit
def _copy_gs(X, Y, n, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    for i in range(pid * BLOCK, n, nprog * BLOCK):
        offs = i + tl.arange(0, BLOCK)
        tl.store(Y + offs, tl.load(X + offs))

def clear_l2():
    d = torch.empty((32, 1024, 1024), dtype=torch.int64, device='cuda')
    d.fill_(42)
    del d

def timeit(fn, n=10):
    for _ in range(3): fn()
    torch.cuda.synchronize()
    ts = []
    for _ in range(n):
        clear_l2()
        s = torch.cuda.Event(True); e = torch.cuda.Event(True)
        s.record(); fn(); e.record()
        torch.cuda.synchronize()
        ts.append(s.elapsed_time(e))
    return sum(ts)/len(ts)

BLOCK = 8192
for mb in [64, 128, 256, 512, 1024]:
    n = mb * 1024 * 1024 // 4
    a = torch.rand(n, device='cuda')
    b = torch.empty_like(a)
    t = timeit(lambda: _copy[(n//BLOCK,)](a, b, BLOCK=BLOCK, num_warps=8))
    print(f'{mb}MB flat copy: {t:.4f} ms -> {2*n*4/t/1e6:.0f} GB/s')
    del a, b; torch.cuda.empty_cache()

# 64MB with different configs
n = 16*1024*1024
