b = torch.empty_like(a)
for blk, warps in [(1024, 4), (2048, 8), (4096, 4), (4096, 16), (8192, 8), (16384, 16)]:
    t = timeit(lambda: _copy[(n//blk,)](a, b, BLOCK=blk, num_warps=warps))
    print(f'64MB copy BLOCK={blk} w={warps} grid={n//blk}: {t:.4f} ms -> {2*n*4/t/1e6:.0f} GB/s')
for grid in [132, 264, 528, 1056]:
    t = timeit(lambda: _copy_gs[(grid,)](a, b, n, BLOCK=4096, num_warps=8))
    print(f'64MB copy gs grid={grid}: {t:.4f} ms -> {2*n*4/t/1e6:.0f} GB/s')
EOF
